/* Offline demo. UI state stays separate from persisted health records. */
(() => {
  'use strict';
  const F = Fitness, E = ExerciseEnergy, $ = s => document.querySelector(s), KEY = 'dailyfitness.v2';
  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = n => Number(n).toLocaleString('zh-CN',{maximumFractionDigits:1});
  const clone = v => JSON.parse(JSON.stringify(v));
  const nowTime = () => new Date().toTimeString().slice(0,5);
  const icons={calendar:'M4 5h16v16H4z M8 3v4m8-4v4M4 10h16m-12 4h1m3 0h1m3 0h1m-9 4h1m3 0h1',activity:'M3 12h4l3-8 4 16 3-8h4',food:'M5 3v7m3-7v7m-6-7v7h6M5 10v11M17 3c-4 4-4 9 0 9h2V3m0 9v9',moon:'M20 14A8.5 8.5 0 0 1 10 3 9 9 0 1 0 20 14z',chart:'M4 4v16h17M7 14l4-5 4 3 5-7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21a8 8 0 0 1 16 0',weight:'M6 6v12m-3-9v6m15-9v12m3-9v6M6 12h12',plus:'M12 5v14M5 12h14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',leaf:'M20 3C8 2 2 9 5 16s15 5 15-13M5 19l10-10',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',trash:'M4 6h16M9 3h6m-9 3 1 15h10l1-15M10 10v7m4-7v7',play:'m8 4 12 8-12 8z',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 4 6 6',folder:'M3 6h7l2 3h9v11H3z'};
  const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.activity}"/></svg>`;
  let db=F.blank(),storageError='',readOnly=false,route='calendar',selected=F.localDate(),month=selected.slice(0,7),onboard=false,trend='weight',range=30,timerEnd=0,restEnabled=true;
  try {const saved=window.AndroidStore?AndroidStore.load():localStorage.getItem(KEY);if(saved)db=F.validateBackup(saved);} catch(e){storageError='无法读取原有记录：'+e.message+'。原数据未被覆盖，请先导出原始数据或恢复备份。';readOnly=true;}
  let welcomed=readOnly||db.profiles.length>0||db.plans.length>0||!!db.draft||db.cardio.length>0||db.strength.length>0||db.meals.length>0||db.sleep.length>0;
  const toast=message=>{const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>t.classList.remove('show'),2600);};
  function commit(change){
    if(readOnly)throw Error('当前数据读取失败。请先导出原始数据，再通过恢复备份修复。');
    const next=clone(db);change(next);F.validateBackup(next);const raw=JSON.stringify(next);
    if(raw.length>4000000)throw Error('本地记录超过 Demo 容量限制，请先导出备份。');
    if(window.AndroidStore){if(!AndroidStore.save(raw))throw Error('保存失败，请检查手机剩余空间。');}else localStorage.setItem(KEY,raw);
    db=next;
  }
  const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
  const idRecord=(kind,id)=>db[kind].find(r=>r.id===id);
  const baseRecord=()=>({id:F.uid(),date:selected,updatedAt:new Date().toISOString()});
  const empty=(title,desc,i='leaf')=>`<div class="empty"><div class="empty-icon">${icon(i)}</div>${esc(title)}<p>${esc(desc)}</p></div>`;
  const navs=[['calendar','calendar','日历'],['train','weight','训练'],['trends','chart','趋势'],['profile','user','我的']];
  function nav(mobile=false){return navs.map(([r,i,t])=>`<button type="button" class="${mobile?'':'nav-btn '}${(route===r||(route==='workout'&&r==='train'))?'active':''}" data-nav="${r}" ${route===r?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span><span>${t}</span></button>`).join('');}
  function render(){
    if(!welcomed&&!onboard){$('#app').innerHTML=`<main class="main" style="margin-left:0;max-width:none"><div class="welcome"><div class="welcome-hero"><img class="intro-icon" src="icon.svg" alt="" width="58" height="58"><div class="eyebrow brand-name">daily fitness</div><h1>把每一天，<br>练成更好的自己。</h1><p>运动、好好吃饭、安心睡眠。<br>从一份属于自己的日常记录开始。</p></div><div class="card"><h2>先认识一下你</h2><p class="tip">身体资料用于生成变化曲线与基础代谢估算。所有记录保存在当前设备。</p>${profileForm(null,true)}</div><button class="text-btn space-top" data-act="skip-welcome">稍后填写，先体验界面</button></div></main>`;bindProfile(true);return;}
    const headers={calendar:['YOUR DAILY BALANCE','daily fitness','让每一份努力，都有迹可循。'],train:['MAKE IT A ROUTINE','今天，练什么？','从熟悉的计划开始，也可以自由记录。'],trends:['SMALL STEPS, REAL PROGRESS','看见自己的变化','每一次记录，都是进步的起点。'],profile:['A LITTLE ABOUT YOU','我的健康档案','记录当下，也留住改变的过程。'],workout:['ONE SET AT A TIME','专注这一组','记录实际完成的重量与次数。']};const h=headers[route];
    $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="row"><img class="brand-mark" src="icon.svg" alt="" width="40" height="40"><div><div class="brand">daily fitness</div><div class="brand-sub">运动 · 饮食 · 睡眠</div></div></div><nav aria-label="主导航">${nav()}</nav><div class="sidebar-foot"><strong>一点点，成为日常。</strong>运动 · 饮食 · 睡眠<br>离线记录 · Demo 0.3</div></aside><main class="main"><header class="page-header row between"><div><div class="eyebrow">${h[0]}</div><h1 class="${route==='calendar'?'page-brand':''}">${route==='calendar'?'<img class="page-brand-icon" src="icon.svg" alt="" width="40" height="40">':''}${h[1]}</h1><p class="subtitle">${h[2]}</p></div><button class="avatar" aria-label="查看个人资料" data-nav="profile">${icon('user')}</button></header>${storageError?`<div class="storage-alert" role="alert">${esc(storageError)}<br><button class="text-btn" data-act="raw-export">导出原始数据</button> <button class="text-btn" data-act="import">恢复备份</button> <button class="text-btn" data-act="clear-data">清空数据</button></div>`:''}${route==='calendar'?calendarPage():route==='train'?trainPage():route==='trends'?trendsPage():route==='profile'?profilePage():workoutPage()}</main><nav class="bottom-nav" aria-label="底部导航">${nav(true)}</nav></div>`;
    if(route==='workout')bindSetForm();
    if(route==='trends')bindTrend();
    tick();
  }
  function calendarPage(){
    const s=F.summary(db,selected),bmr=F.metabolism(F.profileAt(db,selected));
    const first=new Date(month+'-01T12:00:00'),offset=(first.getDay()+6)%7,days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),count=Math.ceil((offset+days)/7)*7;
    let cells='';for(let i=0;i<count;i++){const d=F.shiftDay(month+'-01',i-offset),sum=F.summary(db,d),draft=db.draft?.date===d;cells+=`<button class="day ${d.slice(0,7)!==month?'other ':''}${d===selected?'selected ':''}${d===F.localDate()?'is-today':''}" data-date="${d}" aria-pressed="${d===selected}" aria-label="${d}${sum.cardio.length||sum.strength.length?'，有运动':''}${sum.meals.length?'，有饮食':''}${sum.sleep?'，有睡眠':''}${draft?'，训练进行中':''}"><span>${Number(d.slice(-2))}</span><span class="dots">${sum.cardio.length||sum.strength.length||draft?'<i class="dot"></i>':''}${sum.meals.length?'<i class="dot food"></i>':''}${sum.sleep?'<i class="dot sleep"></i>':''}</span></button>`;}
    return `<div class="calendar-layout"><div class="calendar-column"><section class="card calendar-card" aria-label="月历"><div class="row between calendar-head"><div><div class="eyebrow">${first.getFullYear()}</div><div class="month-title">${first.getMonth()+1} 月<span class="muted" style="font-size:13px;font-weight:400;margin-left:9px">生活日历</span></div></div><div class="month-actions"><button data-act="prev-month" aria-label="上个月">${icon('left')}</button><button class="today-btn" data-act="today">今天</button><button data-act="next-month" aria-label="下个月">${icon('right')}</button></div></div><div class="weekdays">${['一','二','三','四','五','六','日'].map(d=>`<span>${d}</span>`).join('')}</div><div class="days">${cells}</div><div class="calendar-legend"><span><i class="dot"></i>运动</span><span><i class="dot food"></i>饮食</span><span><i class="dot sleep"></i>睡眠</span></div></section><div class="daily-note"><h3>不必完美，保持记录就好。</h3><p>一点运动，一餐好饭，一夜好眠。<br>照顾自己，从今天开始。</p>${icon('leaf')}</div></div><div><div class="report-heading row between"><h2>${selected===F.localDate()?'今天':esc(selected.slice(5).replace('-',' 月 ')+' 日')}的记录</h2><small style="font-size:11px">${esc(new Date(selected+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'long'}))}</small></div><div class="quick-add"><button data-act="add-sport">${icon('plus')}运动</button><button data-act="meal">${icon('plus')}饮食</button><button data-act="sleep">${icon('plus')}睡眠</button></div><div class="stack">${db.draft?.date===selected?draftBanner():''}<section class="card"><div class="card-title"><h2><span class="section-icon">${icon('activity')}</span>运动</h2><button class="add-small" data-act="add-sport" aria-label="添加运动">${icon('plus')}</button></div>${energyReport(selected)}${s.cardio.length||s.strength.length?`<div>${s.cardio.map(r=>`<button class="record-row" data-edit="cardio" data-id="${r.id}"><span><span class="title">${esc(r.type)}</span><span class="detail" style="display:block">${cardioDetail(r)}${cardioEnergyHint(r)}</span></span><span class="value">${fmt(r.minutes)} <small>分钟</small></span></button>`).join('')}${s.strength.map(r=>`<button class="record-row" data-edit="strength" data-id="${r.id}"><span><span class="title">${esc(r.name)}</span><span class="detail" style="display:block">${esc(r.equipment)} · ${r.muscles.join('')} · ${r.sets.length} 组</span></span><span style="text-align:right;font-size:11px">${F.groupedSets(r).map(g=>`${fmt(g.weight)} kg × ${g.reps} 次 × ${g.count} 组`).join('<br>')}</span></button>`).join('')}</div>`:empty('今天的运动，等你开始','散步十分钟，也值得记下来。','activity')}</section><section class="card"><div class="card-title"><h2><span class="section-icon food">${icon('food')}</span>饮食</h2><button class="add-small" data-act="meal" aria-label="添加饮食">${icon('plus')}</button></div><div class="nutrition-total"><div><div class="eyebrow" style="letter-spacing:1px;margin-bottom:5px">当日摄入</div><div class="big-value">${fmt(s.kcal)}<small>kcal</small></div></div><span class="badge orange">${s.meals.length} 餐已记录</span></div><div class="macro-grid">${[['蛋白质',s.protein],['碳水',s.carbs],['脂肪',s.fat]].map(([t,v])=>`<div class="macro">${t}<strong>${fmt(v)} <small style="font-size:11px">g</small></strong></div>`).join('')}</div><p class="bmr-note">${bmr?`基础代谢估算 ${bmr.low}–${bmr.high} kcal / 日<br>仅作参照，非全天总消耗或建议摄入目标。`:'填写成年人的身体资料后，可查看基础代谢估算。'}</p>${s.meals.map(r=>`<button class="record-row" data-edit="meals" data-id="${r.id}"><span><span class="title">${esc(r.name)}</span><span class="detail" style="display:block">${r.time} · 蛋白 ${fmt(r.protein)} / 碳水 ${fmt(r.carbs)} / 脂肪 ${fmt(r.fat)} g</span></span><span class="value">${fmt(F.mealCalories(r))}<small> kcal</small></span></button>`).join('')}</section><section class="card"><div class="card-title"><h2><span class="section-icon sleep">${icon('moon')}</span>睡眠</h2><button class="add-small" data-act="sleep" aria-label="记录或编辑睡眠">${icon('plus')}</button></div>${s.sleep?`<button style="width:100%;text-align:left" data-edit="sleep" data-id="${s.sleep.id}"><div class="row between"><div class="big-value">${fmt(F.sleepHours(s.sleep.start,s.sleep.end))}<small>小时</small></div><span class="badge purple">${s.sleep.awakening?'有起夜':'未起夜'}</span></div><div class="sleep-times"><span>入睡 ${s.sleep.start.slice(5).replace('T',' ')}</span><span class="sleep-line"></span><span>起床 ${s.sleep.end.slice(11)}</span></div><p class="tip">按记录时段计算，归到起床当天。</p></button>`:empty('昨晚，睡得怎么样？','记录入睡与起床时间，照顾好恢复。','moon')}</section></div></div></div>`;
  }
  function cardioDetail(r){return [r.stroke||null,r.poolLength?`${r.poolLength} m 池 × ${r.laps} 趟（单程）`:null,r.distance!==null?`${fmt(F.distanceFromKm(r.distance,r.distanceUnit||'km'))} ${r.distanceUnit||'km'}`:null,r.speed!==null?`${F.speedFromKmh(r.speed,r.speedUnit||'km/h').toLocaleString('zh-CN',{maximumFractionDigits:r.speedUnit==='h/km'?4:2})} ${r.speedUnit==='min/km'?'分钟/公里':r.speedUnit==='h/km'?'小时/公里':'km/h'}`:null,r.slope!==null?`坡度 ${fmt(r.slope)}%`:null,r.height!==null?`爬升 ${fmt(r.height)} m`:null,r.floors!==null?`${r.floors} 层 × ${r.steps} 台阶`:null,r.count!==null?`${r.count} 个`:null].filter(Boolean).join(' · ')||'有氧运动';}
  function cardioEnergyHint(r){const e=E.record(db,r);return e?` · 约 ${fmt(e.netKcal)} kcal（额外）`:'';}
  function energyReport(date){
    const e=E.day(db,date);if(!e.estimated&&!e.missing)return '';
    return `<div class="exercise-energy-report"><span>运动额外消耗 · 估算</span><strong>${e.estimated?fmt(e.active):'—'} <small>kcal</small></strong><p>${e.estimated?'不含同期静息消耗；不是手表实测值。':esc(E.reason(db,date))}${e.missing?` ${e.missing} 项记录尚不能估算，未按 0 计入。`:''}</p><details><summary>估算依据</summary><p>采用 2024 Adult Compendium 的 MET 参照，适用 19–59 岁成人。按当日可用体重与运动时长计算；运动额外消耗扣除 1 MET 的同期静息部分。运动期间总消耗约 ${e.estimated?fmt(e.gross):'—'} kcal（含静息）。</p><a href="https://pacompendium.com/adult-compendium/" target="_blank" rel="noopener">查看 MET 来源</a></details></div>`;
  }
  function strengthEnergyDetails(r){
    const session=(db.sessions||[]).find(s=>s.id===(r.sessionId||r.id)),e=session?.energy||(session?.minutes?E.strength(db,r.date,session.minutes,session.effort):null);
    return `<div class="exercise-energy-note"><strong>本场力量训练${session?.minutes?' · '+fmt(session.minutes)+' 分钟':''}</strong><p>${e?`额外消耗约 ${fmt(e.netKcal)} kcal · ${esc(e.label)}。同一场只计一次，不按动作重复累计。`:'补充整场时长与身体资料后，可估算消耗；不直接用重量和次数推算。'}</p><button type="button" class="text-btn" data-act="session-energy" data-id="${r.id}">填写或修改本场时长</button></div>`;
  }
  function draftBanner(){return `<div class="banner"><div><strong>训练进行中 · ${esc(db.draft.muscle)}</strong><br><small>${esc(db.draft.date)} · ${db.draft.finished.length} 个动作已完成</small></div><button class="btn" data-nav="workout">继续训练</button></div>`;}
  function trainPage(){return `${db.draft?draftBanner():''}<div class="page-grid"><section class="card full"><div class="card-title"><h2>快速开始</h2><span class="badge">${esc(selected)}</span></div><div class="start-grid"><button class="start-tile" data-act="cardio">${icon('activity')}<strong>有氧运动</strong><small>跑步、游泳、骑行…</small></button><button class="start-tile" data-act="big3">${icon('weight')}<strong>三大项</strong><small>卧推、深蹲、硬拉</small></button><button class="start-tile" data-act="free-strength">${icon('plus')}<strong>自由力量训练</strong><small>选择部位，添加动作</small></button></div></section><section class="card full"><div class="card-title"><h2>${icon('folder')} 我的分化计划</h2><button class="btn secondary" data-act="plan">${icon('plus')}新建计划</button></div>${db.plans.length?db.plans.map(p=>`<div class="space-top"><div class="row between"><div><h3>${esc(p.name)}</h3><small>${p.days.length} 个训练日 · 每日一个部位</small></div><button class="text-btn" data-act="plan-edit" data-id="${p.id}">编辑</button></div>${p.days.map((m,i)=>`<div class="plan-day"><div class="row"><span class="day-number">${i+1}</span><div><strong>${esc(m)}部训练</strong>${p.cursor===i?'<span class="badge" style="margin-left:9px">下一训练日</span>':''}</div></div><button class="btn secondary" data-start-plan="${p.id}" data-day="${i}">开始训练</button></div>`).join('')}</div>`).join(''):empty('建一份适合自己的训练计划','三、四、五、六分化；训练日之间可以休息。','folder')}<p class="tip">计划中的部位按训练日轮转。结束今天的训练后推进；历史补录不改变计划进度。</p></section></div>`;}
  function profilePage(){const p=[...db.profiles].sort((a,b)=>a.date.localeCompare(b.date)||a.updatedAt.localeCompare(b.updatedAt)).at(-1);return `<div class="stack"><div class="metric-grid">${[['体重',p?.weight,'kg'],['腰围',p?.waist,'cm'],['臂围',p?.arm,'cm'],['预估体脂',p?.bodyFat,'%']].map(([t,v,u])=>`<div class="metric-box"><small>${t}</small><strong>${v===null||v===undefined?'—':fmt(v)} <small>${u}</small></strong></div>`).join('')}</div><div class="page-grid"><section class="card"><div class="card-title"><h2>身体资料</h2><button class="btn secondary" data-act="profile">新增测量</button></div>${p?`<p>${p.height} cm · ${p.age} 岁 · ${p.sex==='male'?'男':p.sex==='female'?'女':'未指定性别'}</p><p class="tip">最近记录：${p.date}。每次保存新增一条测量，保留历史。</p>`:empty('还没有身体资料','添加一次测量，从今天开始观察变化。','user')}<div class="measure-list space-top">${[...db.profiles].sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt)).map(r=>`<button class="record-row" data-edit="profiles" data-id="${r.id}"><span><span class="title">${r.date}</span><span class="detail" style="display:block">腰围 ${r.waist??'—'} cm · 臂围 ${r.arm??'—'} cm · 体脂 ${r.bodyFat??'—'}%</span></span><strong>${fmt(r.weight)} kg</strong></button>`).join('')}</div></section><section class="card"><h2>数据与设置</h2><button class="settings-row" data-act="export"><span>${icon('download')} 导出备份</span>${icon('right')}</button><button class="settings-row" data-act="import"><span>${icon('upload')} 恢复备份</span>${icon('right')}</button><button class="settings-row" data-act="custom-cardio"><span>${icon('activity')} 添加自定义有氧</span>${icon('right')}</button><button class="settings-row" data-act="clear-data"><span>清空全部数据</span>${icon('trash')}</button><button class="settings-row" data-act="about"><span>计算规则与版本说明</span>${icon('right')}</button><p class="tip">哑铃默认记录总重。杠铃分开记录片重与杆重，默认杆重 20 kg，每个动作可修改。</p><p class="tip">卸载或清除应用数据会删除本地记录，请先导出备份。备份包含个人健康记录，请自行妥善保管。</p></section></div></div>`;}
  const trendMetrics={weight:['体重','kg','身体'],waist:['腰围','cm','身体'],arm:['臂围','cm','身体'],bodyFat:['预估体脂','%','身体'],minutes:['有氧时长','分钟','运动'],exerciseKcal:['运动额外消耗','kcal','运动'],sets:['力量组数','组','运动'],volume:['力量训练容量','kg·次','运动'],kcal:['饮食摄入','kcal','饮食'],protein:['蛋白质摄入','g','饮食'],carbs:['碳水摄入','g','饮食'],fat:['脂肪摄入','g','饮食'],sleep:['睡眠时段','小时','睡眠']};
  function trendPoints(){const from=F.shiftDay(F.localDate(),-(range-1)),to=F.localDate();if(['weight','waist','arm','bodyFat'].includes(trend)){const dates=[...new Set(db.profiles.filter(r=>r.date>=from&&r.date<=to).map(r=>r.date))].sort();return dates.map(date=>({date,value:F.profileAt(db,date)?.[trend]})).filter(p=>p.value!==null&&p.value!==undefined);}const dates=[...new Set([...db.cardio,...db.strength,...db.meals,...db.sleep].map(r=>r.date))].filter(d=>d>=from&&d<=to).sort();return dates.map(date=>{const s=F.summary(db,date);let value=null;if(trend==='sleep')value=s.sleep?F.sleepHours(s.sleep.start,s.sleep.end):null;else if(['kcal','protein','carbs','fat'].includes(trend))value=s.meals.length?s[trend]:null;else if(trend==='exerciseKcal'){const e=E.day(db,date);value=e.estimated?e.active:null;}else if(trend==='minutes')value=s.cardio.length?s.minutes:null;else value=s.strength.length?s[trend]:null;return{date,value};}).filter(p=>p.value!==null);}
  function trendsPage(){const points=trendPoints(),[title,unit,group]=trendMetrics[trend];return `<div class="pill-tabs">${['身体','运动','饮食','睡眠'].map(g=>`<button class="${g===group?'active':''}" data-trend-group="${g}">${g}</button>`).join('')}</div><section class="card"><div class="chart-controls"><label class="field"><span>观察指标</span><select id="trend-metric">${Object.entries(trendMetrics).filter(([,v])=>v[2]===group).map(([k,v])=>`<option value="${k}" ${k===trend?'selected':''}>${v[0]}</option>`).join('')}</select></label><label class="field"><span>时间范围</span><select id="trend-range">${[7,30,90,365].map(n=>`<option value="${n}" ${n===range?'selected':''}>最近 ${n} 天</option>`).join('')}</select></label></div>${points.length?`<div class="chart-stats"><div><span>最近一次 · ${points.at(-1).date}</span><strong>${fmt(points.at(-1).value)} <small style="font-size:12px">${unit}</small></strong></div><div><span>记录天数</span><strong>${points.length} <small style="font-size:12px">天</small></strong></div></div>${chartSvg(points,title,unit)}<p class="tip">仅显示已记录的数据，空缺日期不当作 0。${trend==='volume'?'容量按外部总重量 × 次数相加，不含自重；不同动作与器械不能直接比较。':''}</p><details class="space-top"><summary>查看记录明细</summary><table class="data-table"><thead><tr><th>日期</th><th>${title}（${unit}）</th></tr></thead><tbody>${points.map(p=>`<tr><td>${p.date}</td><td>${fmt(p.value)}</td></tr>`).join('')}</tbody></table></details>`:`<div class="trend-empty">${icon('chart')}<h3>变化，从第一条记录开始</h3><p class="tip">最近 ${range} 天还没有${title}记录。</p><button class="btn secondary space-top" data-nav="${group==='身体'?'profile':'calendar'}">去记录</button></div>`}</section>`;}
  function chartSvg(points,title,unit){const values=points.map(p=>p.value),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.2,hi*.03,1),min=Math.max(0,lo-pad),max=hi+pad,W=700,H=270,L=62,R=25,T=20,B=42,start=new Date(F.shiftDay(F.localDate(),-(range-1))+'T12:00:00').getTime(),end=new Date(F.localDate()+'T12:00:00').getTime(),x=p=>L+(new Date(p.date+'T12:00:00').getTime()-start)/(end-start||1)*(W-L-R),y=v=>H-B-(v-min)/(max-min)*(H-T-B);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${title}趋势，${points.length} 个记录点，单位 ${unit}">${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return`<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-12}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`;}).join('')}<polyline class="chart-line" points="${points.map(p=>`${x(p)},${y(p.value)}`).join(' ')}"/>${points.map(p=>`<circle class="chart-dot" cx="${x(p)}" cy="${y(p.value)}" r="4"><title>${p.date}：${fmt(p.value)} ${unit}</title></circle>`).join('')}<text x="${L}" y="${H-10}">${F.shiftDay(F.localDate(),-(range-1)).slice(5)}</text><text x="${W-R}" y="${H-10}" text-anchor="end">${F.localDate().slice(5)}</text></svg>`;}
  function bindTrend(){$('#trend-metric').onchange=e=>{trend=e.target.value;render();};$('#trend-range').onchange=e=>{range=Number(e.target.value);render();};}
  function dialog(title,body){const m=$('#modal');m.innerHTML=`<div class="modal-header"><h2 id="dialog-title">${esc(title)}</h2><button class="round-btn" data-act="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
  function close(){$('#modal').close();}
  function field(name,label,value='',opts={}){const {type='number',unit='',min=0,max=2000,step='any',required=true}=opts;return `<label class="field"><span>${esc(label)}${unit?' · '+esc(unit):''}${!required?'（选填）':''}</span><input name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${min}" max="${max}" step="${step}" inputmode="${step==='1'?'numeric':'decimal'}"`:''} ${type==='text'?'maxlength="80"':''} ${required?'required':''}></label>`;}
  const selectField=(name,label,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
  const formEnd=(label='保存记录',del='')=>`<div class="form-error" role="alert" id="form-error"></div><div class="form-actions">${del}<button type="button" class="btn ghost" data-act="close">取消</button><button type="submit" class="btn">${label}</button></div>`;
  const deleteBtn=(kind,id)=>`<button type="button" class="btn danger" data-delete="${kind}" data-id="${id}">删除</button>`;
  function bindForm(handler){const form=$('#record-form');form.onsubmit=e=>{e.preventDefault();try{handler(new FormData(form),form);}catch(err){$('#form-error').textContent=err.message;$('#form-error').scrollIntoView({block:'nearest'});}};}
  const val=(fd,k)=>Number(fd.get(k)),opt=(fd,k)=>fd.get(k)===''||fd.get(k)===null?null:Number(fd.get(k));
  function profileForm(p,first=false){const r=p||{...baseRecord(),date:F.localDate(),height:'',weight:'',age:'',sex:'unspecified',waist:null,arm:null,bodyFat:null};return `<form id="record-form"><div class="form-grid space-top">${field('height','身高',r.height,{unit:'cm',min:80,max:250})}${field('weight','体重',r.weight,{unit:'kg',min:20,max:400})}${field('age','年龄',r.age,{unit:'岁',min:10,max:120,step:'1'})}${selectField('sex','性别',[['unspecified','暂不指定'],['male','男'],['female','女']],r.sex)}${field('waist','腰围',r.waist,{unit:'cm',min:20,max:250,required:false})}${field('arm','臂围',r.arm,{unit:'cm',min:10,max:100,required:false})}${field('bodyFat','预估体脂',r.bodyFat,{unit:'%',min:1,max:75,required:false})}${field('date','测量日期',r.date,{type:'date'})}</div><p class="tip">估算基础代谢需成年人的身高、体重、年龄与性别。体脂是自填估计值。</p><div class="form-error" id="form-error" role="alert"></div><div class="form-actions">${p?deleteBtn('profiles',p.id):''}${first?'':'<button type="button" class="btn ghost" data-act="close">取消</button>'}<button class="btn ${first?'wide':''}" type="submit">${first?'开启我的健康日历':'保存测量'}</button></div></form>`;}
  function bindProfile(first=false,p=null){bindForm(fd=>{const r={...(p||baseRecord()),date:String(fd.get('date')),height:val(fd,'height'),weight:val(fd,'weight'),age:val(fd,'age'),sex:String(fd.get('sex')),waist:opt(fd,'waist'),arm:opt(fd,'arm'),bodyFat:opt(fd,'bodyFat'),updatedAt:new Date().toISOString()};F.validateProfile(r);commit(next=>{if(p)next.profiles[next.profiles.findIndex(x=>x.id===p.id)]=r;else next.profiles.push(r);});welcomed=true;close();render();toast('身体测量已保存');});}
  function openProfile(p=null){const latest=[...db.profiles].sort((a,b)=>a.date.localeCompare(b.date)||a.updatedAt.localeCompare(b.updatedAt)).at(-1);const initial=p|| (latest?{...latest,id:F.uid(),date:F.localDate(),updatedAt:new Date().toISOString()}:null);dialog(p?'编辑身体测量':'新增身体测量',profileForm(initial));if(!p){const del=$('#record-form [data-delete]');if(del)del.remove();}bindProfile(false,p);}
  function openCardio(r=null){
    const distanceTypes=['跑步','游泳','骑行','散步','爬坡','划船'];
    let source='distance',distanceUnit=r?.distanceUnit||(r?.type==='游泳'?'m':'km'),speedUnit=r?.speedUnit||'km/h';
    const speedChoices=[['km/h','km/h'],['min/km','分钟/公里'],['h/km','小时/公里']];
    const precise=n=>n===null||!Number.isFinite(n)?'':String(Number(n.toFixed(6)));
    const metric=(name,label,value,unit,opts={})=>{
      const options=opts.choices;
      return `<div class="field metric-field"><label class="metric-label" for="cardio-${name}">${esc(label)}</label><div class="metric-input"><input id="cardio-${name}" name="${name}" type="number" inputmode="${opts.step==='1'?'numeric':'decimal'}" min="${opts.min??0}" max="${opts.max??2000}" step="${opts.step||'any'}" value="${esc(value??'')}" ${opts.required?'required':''} ${opts.readonly?'readonly':''}>${options?`<select name="${opts.unitName}" aria-label="${name==='distance'?'距离单位':'速度单位'}">${options.map(([v,t])=>`<option value="${v}" ${v===unit?'selected':''}>${t}</option>`).join('')}</select>`:`<span class="metric-unit">${esc(unit)}</span>`}</div></div>`;
    };
    dialog(r?'编辑有氧记录':'记录有氧运动',`<form id="record-form" class="cardio-form"><div class="form-grid">${field('date','记录日期',r?.date||selected,{type:'date'})}${selectField('type','运动类型',[...F.CARDIO,...db.customCardio],r?.type||'跑步')}</div><div id="swim-options"></div><div id="cardio-fields" class="form-grid space-top"></div><p class="tip" id="cardio-help"></p><div id="cardio-energy-options" class="space-top"></div><div id="cardio-energy-preview" class="exercise-energy-note" role="status" aria-live="polite"></div><button type="button" class="text-btn space-top" data-act="custom-cardio">＋ 自定义运动项目</button>${formEnd('保存运动',r?deleteBtn('cardio',r.id):'')}</form>`);
    const isPool=()=>$('#swim-mode')?.value==='pool';
    const number=name=>{const v=$(`[name=${name}]`)?.value;return v===undefined||v===''?null:Number(v);};
    const recalc=()=>{
      const minutes=number('minutes');if(!minutes||minutes<=0)return;
      const d=$('[name=distance]'),s=$('[name=speed]');if(!d||!s)return;
      try{
        if(isPool()){
          const laps=number('laps'),pool=Number($('[name=poolLength]').value);
          if(laps>0&&Number.isInteger(laps)){const km=pool*laps/1000;d.value=precise(F.distanceFromKm(km,distanceUnit));s.value=speedUnit==='km/h'?F.speedFromKmh(km/minutes*60,speedUnit).toFixed(2):precise(F.speedFromKmh(km/minutes*60,speedUnit));}
          else{d.value='';s.value='';}
        }else{
          const km=F.distanceToKm(number('distance'),distanceUnit),kmh=F.speedToKmh(number('speed'),speedUnit);
          if(source==='speed'&&kmh>0)d.value=precise(F.distanceFromKm(kmh*minutes/60,distanceUnit));
          else if(km>0)s.value=speedUnit==='km/h'?F.speedFromKmh(km/minutes*60,speedUnit).toFixed(2):precise(F.speedFromKmh(km/minutes*60,speedUnit));
          else if(kmh>0)d.value=precise(F.distanceFromKm(kmh*minutes/60,distanceUnit));
        }
      }catch{/* Keep partial input while typing. Submit reports the actionable error. */}
    };
    const updateMetrics=(initial=false)=>{
      const type=$('[name=type]').value,minutes=number('minutes')??(initial?r?.minutes:'')??'',same=type===r?.type,pool=isPool();
      let html=metric('minutes',type==='游泳'?'总运动时间':'运动时间',minutes,'分钟',{min:.1,max:1440,required:true});
      if(distanceTypes.includes(type)){
        const distance=same?F.distanceFromKm(r.distance,distanceUnit):'',speed=same?F.speedFromKmh(r.speed,speedUnit):'';
        html+=metric('distance',pool?'自动计算距离':'运动距离（可补算）',precise(distance),distanceUnit,{choices:[['m','米'],['km','千米']],unitName:'distanceUnit',max:distanceUnit==='m'?2000000:2000,readonly:pool});
        html+=metric('speed',pool?'自动计算速度':'运动速度 / 配速',precise(speed),speedUnit,{choices:speedChoices,unitName:'speedUnit',max:100000,readonly:pool});
      }
      if(type==='爬坡')html+=metric('slope','坡度',same?r.slope:'','%',{max:100,required:true});
      if(type==='登山')html+=metric('height','累计爬升高度',same?r.height:'','m',{min:1,max:20000,required:true});
      if(type==='爬楼'){html+=metric('floors','楼层数',same?r.floors:'','层',{min:1,max:10000,step:'1',required:true});html+=metric('steps','每层台阶数',same?r.steps:'','级',{min:1,max:1000,step:'1',required:true});}
      if(type==='跳绳')html+=metric('count','跳绳个数',same?r.count:'','个',{min:1,max:1000000,step:'1',required:true});
      if(pool)html+=metric('laps','单程趟数（非来回）',same?r.laps:'','趟',{min:1,max:10000,step:'1',required:true});
      $('#cardio-fields').innerHTML=html;
      $('#cardio-help').textContent=pool?'总距离 = 泳池长度 × 单程趟数。游到对岸计 1 趟，游一个来回计 2 趟；速度由总距离与总时间计算。':distanceTypes.includes(type)?'填写时间，再填写距离或速度任意一项，另一项自动补算。修改距离或速度后，会更新对应值。坡度单独记录，不改变速度 × 时间的距离换算。':'记录实际运动时间与对应数据。';
      $('[name=minutes]').oninput=recalc;
      if($('[name=distance]')){
        $('[name=distance]').oninput=()=>{source='distance';recalc();};
        $('[name=speed]').oninput=()=>{source='speed';recalc();};
        $('[name=distanceUnit]').onchange=e=>{const previous=distanceUnit,km=F.distanceToKm(number('distance'),previous);distanceUnit=e.target.value;$('[name=distance]').max=distanceUnit==='m'?2000000:2000;$('[name=distance]').value=precise(F.distanceFromKm(km,distanceUnit));};
        $('[name=speedUnit]').onchange=e=>{let kmh=null;try{kmh=F.speedToKmh(number('speed'),speedUnit);}catch{}speedUnit=e.target.value;$('[name=speed]').value=precise(F.speedFromKmh(kmh,speedUnit));const help=$('#cardio-help');help.textContent=help.textContent.split(' 配速提示：')[0]+(speedUnit==='km/h'?'':' 配速提示：使用小数，6.5 分钟/公里为 6 分 30 秒，0.1 小时/公里为 6 分钟/公里。');};
      }
      if($('[name=laps]'))$('[name=laps]').oninput=recalc;
      recalc();
    };
    const updateType=(initial=false)=>{
      const type=$('[name=type]').value;
      $('#swim-options').innerHTML=type==='游泳'?`<div class="form-grid space-top">${selectField('stroke','泳姿',F.STROKES,r?.stroke||'自由泳')}<label class="field"><span>记录方式</span><select id="swim-mode"><option value="pool" ${r&&r.type==='游泳'&&!r.poolLength?'':'selected'}>泳池计趟</option><option value="distance" ${r&&r.type==='游泳'&&!r.poolLength?'selected':''}>按距离记录</option></select></label><div id="pool-field">${selectField('poolLength','泳池长度',F.POOLS.map(n=>[n,n+' m 水池']),r?.poolLength||50)}</div></div>`:'';
      const swimMode=$('#swim-mode');
      if(swimMode){const mode=()=>{$('#pool-field').hidden=!isPool();updateMetrics(initial);};swimMode.onchange=mode;$('[name=poolLength]').onchange=recalc;$('#pool-field').hidden=!isPool();}
      updateMetrics(initial);
      const effort=r?.energyEffort||'moderate';
      let extra=['游泳','健身操','登山','划船'].includes(type)?selectField('energyEffort','消耗估算强度',[['moderate','一般 / 休闲'],['vigorous','较高强度 / 训练']],effort):'';
      if(type==='球类运动')extra+=selectField('sport','球类项目（用于估算消耗）',[['','暂不选择，不估算'],...Object.entries(E.SPORTS).map(([k,v])=>[k,v[0]])],r?.sport||'');
      if(type==='划船')extra+=selectField('rowingMode','划船方式',[['ergometer','划船机'],['water','水上休闲划船']],r?.rowingMode||'ergometer');
      if(!F.CARDIO.includes(type))extra+=selectField('energyReference','消耗参照（选填）',[['','暂不选择，不估算'],...Object.entries(E.REFERENCES)],r?.energyReference||'');
      $('#cardio-energy-options').innerHTML=extra?`<div class="form-grid">${extra}</div>`:'';
      updateEnergyPreview();
    };
    const updateEnergyPreview=()=>{
      const form=$('#record-form'),fd=new FormData(form),date=String(fd.get('date'));
      const p=F.profileAt(db,date);
      if(!p||p.age<19||p.age>59){$('#cardio-energy-preview').textContent=E.reason(db,date);return;}
      const candidate={type:String(fd.get('type')),date,minutes:val(fd,'minutes'),slope:opt(fd,'slope'),count:opt(fd,'count'),stroke:fd.get('stroke'),sport:fd.get('sport'),energyEffort:fd.get('energyEffort')||'moderate',rowingMode:fd.get('rowingMode')||'ergometer',energyReference:fd.get('energyReference')||''};
      try{let speed=null;if(isPool()){const d=val(fd,'poolLength')*val(fd,'laps')/1000;speed=d/candidate.minutes*60;}else if(source==='speed'&&opt(fd,'speed')!==null)speed=F.speedToKmh(opt(fd,'speed'),speedUnit);else if(opt(fd,'distance')!==null)speed=F.distanceToKm(opt(fd,'distance'),distanceUnit)/candidate.minutes*60;candidate.speed=speed;
        const e=E.estimate(db,candidate,date);$('#cardio-energy-preview').innerHTML=e?`<strong>额外消耗约 ${fmt(e.netKcal)} kcal</strong><p>${esc(e.label)} · MET ${e.met} · 体重 ${fmt(e.weight)} kg。扣除同期静息消耗，仅作估算。</p>`:'填写运动时间与具体项目后显示估算；不支持的条件暂不估算。';
      }catch{$('#cardio-energy-preview').textContent='填写有效时间、距离或速度后显示估算。';}
    };
    $('[name=type]').onchange=()=>{source='distance';distanceUnit=$('[name=type]').value==='游泳'?'m':'km';updateType(false);};updateType(true);
    $('#record-form').addEventListener('input',updateEnergyPreview);$('#record-form').addEventListener('change',updateEnergyPreview);
    bindForm(fd=>{
      const record={...(r||baseRecord()),date:String(fd.get('date')),type:String(fd.get('type')),minutes:val(fd,'minutes'),updatedAt:new Date().toISOString()};
      for(const k of ['distance','speed','slope','height','floors','steps','count'])record[k]=opt(fd,k);
      delete record.stroke;delete record.poolLength;delete record.laps;
      if(distanceTypes.includes(record.type)){
        let km=F.distanceToKm(opt(fd,'distance'),distanceUnit),kmh=F.speedToKmh(opt(fd,'speed'),speedUnit);
        if(isPool()){
          record.poolLength=val(fd,'poolLength');record.laps=val(fd,'laps');km=record.poolLength*record.laps/1000;kmh=null;
        }else if(source==='speed'&&kmh!==null)km=null;else if(km!==null)kmh=null;
        Object.assign(record,F.resolveCardioMetrics(record.minutes,km,kmh));
        record.distanceUnit=distanceUnit;record.speedUnit=speedUnit;
      }
      if(record.type==='游泳')record.stroke=String(fd.get('stroke'));
      record.energyEffort=String(fd.get('energyEffort')||'moderate');record.sport=String(fd.get('sport')||'');record.rowingMode=String(fd.get('rowingMode')||'ergometer');record.energyReference=String(fd.get('energyReference')||'');
      record.energy=E.estimate(db,record,record.date);
      F.validateRecord('cardio',record);
      commit(next=>{if(r)next.cardio[next.cardio.findIndex(x=>x.id===r.id)]=record;else next.cardio.push(record);});selected=record.date;month=selected.slice(0,7);close();render();toast('有氧运动已保存');
    });
  }
  function openMeal(r=null){
    const N=globalThis.FoodNutrition;
    let foods=clone(r?.foods||[]),method=r?.energyMethod||'manual',picked=null;
    dialog(r?'编辑饮食记录':'记录这一餐',`<form id="record-form"><div class="form-grid">${field('date','记录日期',r?.date||selected,{type:'date'})}${field('time','用餐时间',r?.time||nowTime(),{type:'time'})}${selectField('type','餐次',F.MEALS,r?.type||'早饭')}</div>
      <details class="food-estimator space-top" ${foods.length?'open':''}><summary>${icon('search')}<span>按食物名称估算</span><span class="badge">中餐 / 食物库</span></summary><div class="food-estimator-body">
      ${N?.available?`<label class="field"><span>食物库范围</span><select id="food-source-filter"><option value="all">全部食物</option><option value="tfda">中文食品（含中式食品）</option><option value="usda">USDA 食物</option></select></label><label class="field space-top"><span>食物名称</span><input id="food-query" type="search" maxlength="100" autocomplete="off" placeholder="例如：馒头、水饺、叉烧肉、米饭" aria-describedby="food-search-help"></label><p id="food-search-help" class="tip">按名称选择具体食物，再输入可食用重量。请核对生熟、是否去皮及烹调方式。</p><div id="food-results-status" class="tip" role="status" aria-live="polite"></div><div id="food-results" class="food-results"></div><div id="food-choice" class="food-choice" hidden></div>`:'<p class="tip">食物库暂不可用，请继续使用下面的手动营养素输入。</p>'}
      <div id="food-error" class="form-error" role="alert"></div><div id="meal-foods"></div><p class="food-source-note">来源：<a href="https://data.gov.tw/dataset/8543" target="_blank" rel="noopener">卫福部食品药物管理署 2026 食品营养成分资料集（2026-10-05）</a>及 <a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener">USDA 官方数据</a>。共 ${fmt(N?.count||0)} 项，其中中文食品 ${fmt(N?.tfdaCount||0)} 项。保留熟食、冷冻等样品状态；不同配方有差异，不是餐厅实测值。本地快照，非实时联网搜索。中文数据依<a href="https://data.gov.tw/license" target="_blank" rel="noopener">政府资料开放授权条款第1版</a>使用。</p></div></details>
      <div class="form-section">本餐营养素，可手动修改</div><div class="form-grid">${field('protein','蛋白质',r?.protein??'',{unit:'g'})}${field('carbs','碳水',r?.carbs??'',{unit:'g'})}${field('fat','脂肪',r?.fat??'',{unit:'g'})}<div style="align-self:center"><small>本餐热量估算</small><div class="big-value" style="font-size:28px"><span id="meal-kcal">0</span><small>kcal</small></div></div></div><p class="tip" id="meal-energy-method"></p><p class="tip">食物估算按重量换算；包装食品优先核对包装营养标签。手动录入的是营养素克数，不是食物重量；某项未摄入请填 0。</p>${formEnd('保存饮食',r?deleteBtn('meals',r.id):'')}</form>`);
    const macros=['protein','carbs','fat'];
    const calc=()=>{
      $('#meal-kcal').textContent=fmt(method==='food-database'&&foods.length?F.foodTotals(foods).kcal:F.calories(...macros.map(k=>Number($(`[name=${k}]`).value))));
      $('#meal-energy-method').textContent=method==='food-database'?'已使用食物合计。热量采用 所选食物数据库能量值，可能与简单 4/4/9 换算不同。':foods.length?'当前为手动营养素总量，热量按 4/4/9 计算；所选食物仅保留为估算参考。':'手动换算：蛋白质与碳水 4 kcal/g，脂肪 9 kcal/g。';
    };
    const applyFoods=()=>{
      method=foods.length?'food-database':'manual';
      const total=F.foodTotals(foods);
      for(const k of macros)$(`[name=${k}]`).value=foods.length?total[k]:'';
      calc();renderFoods();
    };
    const renderFoods=()=>{
      if(!foods.length){$('#meal-foods').innerHTML='';return;}
      const total=F.foodTotals(foods);
      $('#meal-foods').innerHTML=`<div class="food-list-title">本餐食物 · ${foods.length} 项</div>${foods.map((food,i)=>{const t=F.foodTotals([food]);return `<div class="meal-food-row"><div><strong>${esc(food.name)}</strong><p>${fmt(food.grams)} g · ${fmt(t.kcal)} kcal</p><small>${esc(N.reference(food))} · ${esc(food.release)}</small></div><button type="button" class="round-btn" data-food-remove="${i}" aria-label="移除${esc(food.name)}">${icon('close')}</button></div>`;}).join('')}<div class="food-totals"><span>合计 <strong>${fmt(total.kcal)} kcal</strong><br><small>蛋白质 ${fmt(total.protein)} g · 碳水 ${fmt(total.carbs)} g · 脂肪 ${fmt(total.fat)} g</small></span>${method==='manual'?'<button type="button" class="btn secondary" id="apply-foods">用食物合计填写</button>':'<span class="badge">已填入营养素</span>'}</div>${method==='manual'?'<p class="tip">点击“用食物合计填写”会替换下面的营养素数值。</p>':''}`;
      if($('#apply-foods'))$('#apply-foods').onclick=()=>{applyFoods();toast('已按食物合计填写，可继续手动修改');};
    };
    const chooseFood=id=>{
      picked=N.get(id);if(!picked)return;
      const source=N.source(picked.source);
      $('#food-choice').hidden=false;
      $('#food-choice').innerHTML=`<strong>${esc(picked.name||picked.description)}</strong>${picked.name?`<p class="food-original">${esc(picked.description)}</p>`:''}<p class="tip">每 100 g：蛋白质 ${fmt(picked.protein)} g · 碳水 ${fmt(picked.carbs)} g · 脂肪 ${fmt(picked.fat)} g · ${fmt(picked.kcal)} kcal</p><p class="food-source-note">${esc(N.reference(picked))} · ${esc(source.release)} · <a href="${esc(source.documentation||N.documentation)}" target="_blank" rel="noopener">查看数据来源</a></p><div class="food-portion-row"><label class="field"><span>可食用重量 · g</span><input id="food-grams" type="text" inputmode="decimal" maxlength="10" value="100" aria-describedby="food-weight-help"></label><button type="button" class="btn" id="add-food">加入本餐</button></div><p id="food-weight-help" class="tip">去除骨、壳等不可食部分；生食物用生重，熟食物用熟重。单项 0.1–5000 g。</p><div id="food-portion-preview" class="food-portion-preview" role="status" aria-live="polite"></div>`;
      const preview=()=>{try{const t=F.foodTotals([N.estimate(picked.id,Number($('#food-grams').value))]);$('#food-portion-preview').textContent=`这份约 ${fmt(t.kcal)} kcal · 蛋白质 ${fmt(t.protein)} g / 碳水 ${fmt(t.carbs)} g / 脂肪 ${fmt(t.fat)} g`;$('#food-error').textContent='';}catch(e){$('#food-portion-preview').textContent='请输入有效的食用重量。';}};
      $('#food-grams').oninput=preview;preview();
      $('#add-food').onclick=()=>{try{
        if(foods.length>=100)throw Error('一餐最多添加 100 项食物。');
        const snapshot=N.estimate(picked.id,Number($('#food-grams').value));
        const blank=macros.every(k=>$(`[name=${k}]`).value==='');
        foods.push(snapshot);
        if(method==='food-database'||blank)applyFoods();else{renderFoods();calc();}
        $('#food-choice').hidden=true;$('#food-choice').innerHTML='';picked=null;
        $('#food-results').innerHTML='';$('#food-results-status').textContent='已加入本餐，可以继续搜索其他食物。';$('#food-query').value='';$('#food-error').textContent='';
      }catch(e){$('#food-error').textContent=e.message;}};
    };
    if(N?.available){
      const search=()=>{
        picked=null;$('#food-choice').hidden=true;$('#food-choice').innerHTML='';$('#food-error').textContent='';
        const q=$('#food-query').value.trim();if(!q){$('#food-results').innerHTML='';$('#food-results-status').textContent='';return;}
        const result=N.search(q,20,$('#food-source-filter').value);
        $('#food-results-status').textContent=result.total?`找到 ${result.total} 项${result.total>20?'，先显示前 20 项，可补充关键词缩小范围':''}；请选择与实际食物相符的一项。`:'没有匹配项。可换常见中文名或英文名；复杂菜肴与品牌食品请按配料或包装标签手动录入。';
        $('#food-results').innerHTML=result.foods.map(f=>`<button type="button" class="food-result" data-food-id="${f.id}"><strong>${esc(f.name||f.description)}</strong>${f.name?`<span class="food-original">${esc(f.description)}</span>`:''}<small>${fmt(f.kcal)} kcal / 100 g · ${f.source==='tfda'?'食药署中文食品 2026-10':f.source==='foundation'?'Foundation 2026-10':'SR Legacy 2018-04'}</small></button>`).join('');
      };
      $('#food-query').oninput=search;$('#food-source-filter').onchange=search;
      $('#food-query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search();}};
      $('#food-results').onclick=e=>{const btn=e.target.closest('[data-food-id]');if(btn)chooseFood(btn.dataset.foodId);};
    }
    $('#meal-foods').onclick=e=>{const btn=e.target.closest('[data-food-remove]');if(!btn)return;foods.splice(Number(btn.dataset.foodRemove),1);if(method==='food-database')applyFoods();else renderFoods();};
    $('#record-form').addEventListener('input',e=>{if(macros.includes(e.target.name)){method='manual';renderFoods();calc();}});
    calc();renderFoods();
    bindForm(fd=>{const type=String(fd.get('type')),date=String(fd.get('date')),record={...(r||baseRecord()),date,time:String(fd.get('time')),type,name:r&&r.type===type&&r.date===date?r.name:F.mealName(db,date,type),protein:val(fd,'protein'),carbs:val(fd,'carbs'),fat:val(fd,'fat'),foods:clone(foods),energyMethod:method,updatedAt:new Date().toISOString()};F.validateRecord('meals',record);commit(next=>{if(r)next.meals[next.meals.findIndex(x=>x.id===r.id)]=record;else next.meals.push(record);});selected=date;month=date.slice(0,7);close();render();toast('饮食记录已保存');});
  }
  function openSleep(r=null){r=r||db.sleep.find(x=>x.date===selected)||null;dialog(r?'编辑睡眠记录':'记录昨晚的睡眠',`<form id="record-form"><div class="stack">${field('start','入睡日期与时间',r?.start||F.shiftDay(selected,-1)+'T23:00',{type:'datetime-local'})}${field('end','起床日期与时间',r?.end||selected+'T07:00',{type:'datetime-local'})}<label class="check-field"><input name="awakening" type="checkbox" ${r?.awakening?'checked':''}>期间有起夜</label></div><p class="tip">自动归到起床当天。每个起床日期保存一条主要睡眠；时长按起止时段计算，不扣除未记录的起夜时间。</p>${formEnd('保存睡眠',r?deleteBtn('sleep',r.id):'')}</form>`);bindForm(fd=>{const end=String(fd.get('end')),record={...(r||baseRecord()),date:end.slice(0,10),start:String(fd.get('start')),end,awakening:fd.get('awakening')==='on',updatedAt:new Date().toISOString()};F.validateRecord('sleep',record);if(db.sleep.some(x=>x.date===record.date&&x.id!==record.id))throw Error('起床当天已有睡眠，请先打开该日期编辑已有记录。');commit(next=>{if(r)next.sleep[next.sleep.findIndex(x=>x.id===r.id)]=record;else next.sleep.push(record);});selected=record.date;month=selected.slice(0,7);close();render();toast('睡眠记录已保存');});}
  function openPlan(p=null){dialog(p?'编辑分化计划':'新建分化计划',`<form id="record-form"><div class="form-grid">${field('name','计划名称',p?.name||'我的三分化',{type:'text'})}${selectField('split','分化方式',[[3,'三分化 · 3 个训练日'],[4,'四分化 · 4 个训练日'],[5,'五分化 · 5 个训练日'],[6,'六分化 · 6 个训练日']],p?.days.length||3)}</div><p class="tip">每个训练日一个部位；训练日之间可以休息。</p><div id="plan-days" class="stack space-top"></div>${formEnd('保存计划',p?deleteBtn('plans',p.id):'')}</form>`);const update=()=>{const n=Number($('[name=split]').value),defaults=['胸','背','腿','肩','臂','腹'];$('#plan-days').innerHTML=Array.from({length:n},(_,i)=>selectField('day'+i,`第 ${i+1} 训练日`,F.MUSCLES,p?.days[i]||defaults[i])).join('');};$('[name=split]').onchange=update;update();bindForm(fd=>{const n=val(fd,'split'),days=Array.from({length:n},(_,i)=>String(fd.get('day'+i)));if(new Set(days).size!==days.length)throw Error('各训练日请选择不同部位。');if(p&&db.draft?.planId===p.id)throw Error('该计划正在训练，请先结束或放弃训练再修改。');commit(next=>{const rec={id:p?.id||F.uid(),name:String(fd.get('name')).trim(),days,cursor:p?Math.min(p.cursor,n-1):0};if(p)next.plans[next.plans.findIndex(x=>x.id===p.id)]=rec;else next.plans.push(rec);});close();render();toast('分化计划已保存');});}
  function muscleSvg(m){return `<svg class="body-figure" viewBox="0 0 160 240" role="img" aria-label="中性人体部位选择示意图"><circle class="body-outline" cx="60" cy="22" r="15"/><path class="body-outline" d="M49 39h22l22 12 17 60-10 5-22-47v55l9 100H69l-9-78-9 78H33l9-100V69l-22 47-10-5 17-60z"/><path class="muscle ${m==='胸'?'selected':''}" data-muscle="胸" tabindex="0" role="button" aria-label="选择胸部" d="M43 53h16v24H43zm18 0h16v24H61z"/><path class="muscle ${m==='肩'?'selected':''}" data-muscle="肩" tabindex="0" role="button" aria-label="选择肩部" d="m28 52 13-6 1 17-18 5zm51-6 13 6 5 16-18-5z"/><path class="muscle ${m==='臂'?'selected':''}" data-muscle="臂" tabindex="0" role="button" aria-label="选择臂部" d="m24 70 12 4-13 30-10-3zm60 4 12-4 11 31-10 3z"/><path class="muscle ${m==='腹'?'selected':''}" data-muscle="腹" tabindex="0" role="button" aria-label="选择腹部" d="M46 80h28v38H46z"/><path class="muscle ${m==='腿'?'selected':''}" data-muscle="腿" tabindex="0" role="button" aria-label="选择腿部" d="M43 126h15l-7 73H37zm19 0h15l6 73H69z"/><path class="body-outline" d="M123 67h20v47h-20z"/><path class="muscle ${m==='背'?'selected':''}" data-muscle="背" tabindex="0" role="button" aria-label="选择背部" d="M124 68h18v44h-18z"/><text x="133" y="132" font-size="11" fill="#647068" text-anchor="middle">背部</text></svg>`;}
  function chooseMuscle(mode='split'){if(db.draft){route='workout';close();render();toast('请继续当前训练，或先结束 / 放弃');return;}dialog(mode==='big3'?'开始三大项':'选择训练部位',`<p class="tip">记录日期：${esc(selected)}</p><div class="muscle-picker space-top">${muscleSvg('胸')}<div class="muscle-options">${F.MUSCLES.map(m=>`<button data-muscle="${m}" class="${m==='胸'?'active':''}">${m}</button>`).join('')}</div></div><p class="tip">每次选择一个部位，再添加该部位的动作。</p><div class="form-actions"><button class="btn" id="start-free">开始记录</button></div>`);let muscle='胸';$('#modal').onclick=e=>{const b=e.target.closest('[data-muscle]');if(!b)return;muscle=b.dataset.muscle;$('#modal .muscle-picker').innerHTML=muscleSvg(muscle)+`<div class="muscle-options">${F.MUSCLES.map(m=>`<button data-muscle="${m}" class="${m===muscle?'active':''}">${m}</button>`).join('')}</div>`;};$('#start-free').onclick=()=>{startSession(mode,muscle);};}
  function startSession(mode,muscle,planId=null,dayIndex=0){if(db.draft){close();route='workout';render();toast('已恢复进行中的训练');return;}const p=db.plans.find(x=>x.id===planId);commit(next=>next.draft={id:F.uid(),date:selected,muscle,mode,split:p?.days.length||3,planId,dayIndex,startedAt:new Date().toISOString(),active:null,finished:[]});close();route='workout';render();openExercise();}
  const exerciseSeeds={胸:['卧推','上斜哑铃卧推','俯卧撑','哑铃飞鸟'],肩:['推举','哑铃侧平举','俯身反向飞鸟'],背:['坐姿划船','哑铃划船','引体向上'],腿:['深蹲','硬拉','弓步蹲','壶铃高脚杯深蹲'],臂:['哑铃弯举','杠铃弯举','臂屈伸'],腹:['卷腹','仰卧举腿','俄罗斯转体']};
  function openExercise(){const d=db.draft;if(!d)return;if(d.active){toast('请先完成当前动作');return;}const seeds=d.mode==='big3'?['卧推','深蹲','硬拉']:exerciseSeeds[d.muscle];const list=[...new Set([...seeds,...db.exercises])];dialog('选择下一个动作',`<form id="record-form"><div class="stack">${field('name','动作名称','',{type:'text'})}${selectField('equipment','运动器械',F.EQUIPMENT,d.mode==='big3'?'杠铃':'哑铃')}<div id="bar-field">${field('barWeight','杠铃杆重',20,{unit:'kg',max:100})}</div><div id="weight-hint" class="tip"></div></div><div id="exercise-list" class="exercise-list"></div><p class="tip">可以选择已有动作，或直接填写自定义动作名称。只继承上次重量，本次次数手动填写。</p>${formEnd('开始这个动作')}</form>`);const updateList=()=>{const q=$('[name=name]').value.trim();$('#exercise-list').innerHTML=list.filter(n=>n.toLowerCase().includes(q.toLowerCase())).map(n=>`<button type="button" class="exercise-option" data-exercise-name="${esc(n)}"><span>${esc(n)}</span>${icon('plus')}</button>`).join('')||'<p class="tip">没有同名动作，可以直接创建。</p>';};const equip=()=>{const e=$('[name=equipment]').value;$('#bar-field').hidden=e!=='杠铃';$('[name=barWeight]').required=e==='杠铃';$('#weight-hint').textContent=e==='杠铃'?'重量输入两侧杠铃片合计，不含杆；报告会另加杆重。':e==='自重'?'自重只记录额外负重；没有额外负重时填 0。':'重量按实际使用的器械总重填写，哑铃也是总重。';const last=F.lastWeight(db,$('[name=name]').value.trim(),e,d.date);if(e==='杠铃')$('[name=barWeight]').value=last.barWeight;};$('[name=name]').oninput=()=>{updateList();};$('[name=equipment]').onchange=equip;$('#exercise-list').onclick=e=>{const b=e.target.closest('[data-exercise-name]');if(b){$('[name=name]').value=b.dataset.exerciseName;equip();}};updateList();equip();bindForm(fd=>{const name=String(fd.get('name')).trim(),equipment=String(fd.get('equipment')),last=F.lastWeight(db,name,equipment,d.date),muscle=d.mode==='big3'?(name==='卧推'?'胸':name==='深蹲'||name==='硬拉'?'腿':d.muscle):d.muscle;if(d.mode==='big3'&&!['卧推','深蹲','硬拉'].includes(name))throw Error('三大项请选择卧推、深蹲或硬拉。');const record={...baseRecord(),date:d.date,sessionId:d.id,name,equipment,barWeight:equipment==='杠铃'?val(fd,'barWeight'):0,muscles:[muscle],mode:d.mode,split:d.split,sets:[],note:'',nextWeight:equipment==='自重'?0:last.weight};F.validateRecord('strength',record,true);commit(next=>{next.draft.active=record;if(!next.exercises.includes(name))next.exercises.push(name);});close();render();});}
  function workoutPage(){const d=db.draft;if(!d){route='train';return trainPage();}const a=d.active;const last=a?db.strength.filter(r=>r.name===a.name&&r.equipment===a.equipment&&r.date<=d.date).sort((x,y)=>x.date.localeCompare(y.date)||x.updatedAt.localeCompare(y.updatedAt)).at(-1):null;return `<div class="workout-top row between"><div><small>${d.date} · ${d.mode==='big3'?'三大项':d.muscle+'部训练'}</small><h2>${a?esc(a.name):'准备好下一个动作'}</h2><small>${d.finished.length} 个动作已完成${a?' · '+a.sets.length+' 组已记录':''}</small></div><span class="badge" style="background:#e2edcd;color:#315b44">运动中</span></div><div class="page-grid"><section class="card full">${a?`<div class="card-title"><h2>${esc(a.name)} <span class="badge">${esc(a.equipment)}</span></h2><button class="text-btn" data-act="history">历史</button></div><p class="tip">${a.equipment==='杠铃'?`本次输入片重，另加杆重 ${a.barWeight} kg。`:'按额外负重或器械总重记录；哑铃按总重。'}${last?'上次记录：'+last.date+'。':'还没有这个动作的历史记录。'}</p><div class="set-header"><span>组</span><span>上次</span><span>输入 kg</span><span>次数</span><span>编辑</span></div>${a.sets.map((s,i)=>`<div class="set-row"><span>${s.warmup?'热':i+1}</span><span class="previous">${last?.sets[i]?`${fmt(last.sets[i].weight)} × ${last.sets[i].reps}`:'—'}</span><strong>${fmt(s.weight)}</strong><strong>${s.reps}</strong><button data-edit-set="${i}" aria-label="编辑第 ${i+1} 组">${icon('check')}</button></div>`).join('')||'<p class="tip">还没有完成组，填写下面的数据开始记录。</p>'}<form id="set-form" class="set-input"><div class="form-grid">${field('weight',a.equipment==='杠铃'?'两侧片重合计':'器械总重 / 额外负重',a.nextWeight??a.sets.at(-1)?.weight??0,{unit:'kg',max:1000})}${field('reps','本组次数','',{unit:'次',min:1,max:1000,step:'1'})}</div><div class="row between wrap space-top"><label class="check-field"><input name="warmup" type="checkbox">热身组</label><small>只记录实际完成的组</small></div><div class="form-error" id="set-error" role="alert"></div><button type="submit" class="btn wide space-top">${icon('check')}记录一组</button></form><div class="timer"><label class="check-field"><input id="rest-enabled" type="checkbox" ${restEnabled?'checked':''}>组间休息</label><strong id="timer-text">${timerEnd?'':'01:30'}</strong><button data-act="timer-reset">重计</button><button data-act="timer-skip">跳过</button></div><div class="form-actions"><button class="btn ghost" data-act="note">动作备注</button><button class="btn" data-act="finish-action" ${!a.sets.length?'disabled':''}>完成动作</button></div>`:`${empty('本次训练由你安排','选择动作，记录每一组真实完成。','weight')}<button class="btn wide space-top" data-act="exercise">${icon('plus')}添加下一个动作</button>`}</section>${d.finished.length?`<section class="card full"><h2>本次已完成</h2>${d.finished.map(r=>`<div class="record-row"><span><span class="title">${esc(r.name)}</span><span class="detail" style="display:block">${esc(r.equipment)} · ${r.sets.filter(s=>!s.warmup).length} 正式组 / ${r.sets.filter(s=>s.warmup).length} 热身组</span></span><strong>${r.sets.length} 组</strong></div>`).join('')}</section>`:''}<div class="full row wrap between"><button class="btn danger" data-act="discard-workout">放弃本次训练</button><button class="btn" data-act="finish-workout" ${!d.finished.length&&!a?.sets.length?'disabled':''}>结束本次训练</button></div></div>`;}
  function bindSetForm(){const form=$('#set-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();try{const fd=new FormData(form),s={weight:val(fd,'weight'),reps:val(fd,'reps'),warmup:fd.get('warmup')==='on',at:new Date().toISOString()};const a=clone(db.draft.active);a.sets.push(s);F.validateRecord('strength',a);commit(next=>{next.draft.active=a;next.draft.active.nextWeight=s.weight;});if(restEnabled)timerEnd=Date.now()+90000;render();toast('第 '+a.sets.length+' 组已保存');}catch(err){$('#set-error').textContent=err.message;}};$('#rest-enabled').onchange=e=>{restEnabled=e.target.checked;if(!restEnabled)timerEnd=0;tick();};}
  function tick(){const t=$('#timer-text');if(t&&timerEnd){const seconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));t.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(!seconds){timerEnd=0;toast('休息结束，准备好再开始下一组');}}}
  setInterval(tick,1000);
  function confirmation(title,message,onConfirm){dialog(title,`<p>${esc(message)}</p><div class="form-actions"><button class="btn ghost" data-act="close">取消</button><button class="btn danger" id="confirm-action">确认</button></div>`);$('#confirm-action').onclick=()=>{try{onConfirm();close();render();}catch(e){toast(e.message);}};}
  function finishWorkout(){
    const d=db.draft;if(!d)return;
    const sets=d.finished.reduce((n,r)=>n+r.sets.length,0)+(d.active?.sets.length||0),elapsed=(Date.now()-new Date(d.startedAt).getTime())/60000;
    const suggested=elapsed>=.1&&elapsed<=1440?Math.round(elapsed*10)/10:'';
    dialog('结束本次训练',`<form id="record-form"><p>已记录 ${sets} 组。结束后将保存到日历。</p><div class="form-grid space-top">${field('sessionMinutes','整场训练时长',suggested,{unit:'分钟',min:.1,max:1440,required:false})}${selectField('sessionEffort','消耗估算强度',[['moderate','一般力量训练'],['vigorous','较高强度力量训练']],'moderate')}</div><p class="tip">默认按开始到现在计时，包含一般组间休息；长时间中断请扣除。可以修改或留空，留空时不估算热量。</p><div id="strength-energy-preview" class="exercise-energy-note" role="status"></div>${formEnd('确认')}</form>`);
    const preview=()=>{const fd=new FormData($('#record-form')),minutes=opt(fd,'sessionMinutes'),e=E.strength(db,d.date,minutes,String(fd.get('sessionEffort')));$('#strength-energy-preview').textContent=e?`本场额外消耗约 ${fmt(e.netKcal)} kcal，采用当日体重 ${fmt(e.weight)} kg、MET ${e.met}；按整场计一次。`:(minutes?E.reason(db,d.date):'未填时长，本场不计入消耗估算。');};$('#record-form').addEventListener('input',preview);$('#record-form').addEventListener('change',preview);preview();
    bindForm(fd=>{const minutes=opt(fd,'sessionMinutes'),effort=String(fd.get('sessionEffort')),energy=E.strength(db,d.date,minutes,effort);commit(next=>{const draft=next.draft;if(draft.active?.sets.length){draft.active.updatedAt=new Date().toISOString();draft.finished.push(draft.active);}next.strength.push(...draft.finished);next.sessions.push({id:draft.id,date:draft.date,minutes,effort,energy});if(draft.planId&&draft.date===F.localDate()){const p=next.plans.find(p=>p.id===draft.planId);if(p)p.cursor=(draft.dayIndex+1)%p.days.length;}next.draft=null;});selected=d.date;month=selected.slice(0,7);route='calendar';timerEnd=0;close();render();toast('本次训练已保存到日历');});
  }
  function editSessionEnergy(recordId){
    const r=idRecord('strength',recordId);if(!r)return;
    const id=r.sessionId||r.id,session=(db.sessions||[]).find(s=>s.id===id);
    dialog('本场力量训练时长',`<form id="record-form"><p class="tip">${r.date} · 同一场的所有动作共用时长，热量只计一次。</p><div class="form-grid">${field('sessionMinutes','整场训练时长',session?.minutes??'',{unit:'分钟',min:.1,max:1440,required:false})}${selectField('sessionEffort','消耗估算强度',[['moderate','一般力量训练'],['vigorous','较高强度力量训练']],session?.effort||'moderate')}</div><p class="tip">包含一般组间休息，不以重量和次数推算。留空则取消本场估算。</p>${formEnd('保存时长')}</form>`);
    bindForm(fd=>{const minutes=opt(fd,'sessionMinutes'),effort=String(fd.get('sessionEffort')),rec={id,date:r.date,minutes,effort,energy:E.strength(db,r.date,minutes,effort)};commit(next=>{const i=next.sessions.findIndex(s=>s.id===id);if(i>=0)next.sessions[i]=rec;else next.sessions.push(rec);});close();render();toast('整场时长与消耗已更新');});
  }
  function editStrength(r){dialog('查看与修正训练',`<h3>${esc(r.name)} · ${esc(r.equipment)}</h3><p class="tip">${r.date} · ${r.equipment==='杠铃'?'输入为片重，另加 '+r.barWeight+' kg 杆重':'输入为器械总重 / 额外负重'}。点击一组修改或删除。</p>${r.sets.map((s,i)=>`<button class="record-row" data-record-set="${i}" data-id="${r.id}"><span>第 ${i+1} 组 ${s.warmup?'· 热身':''}</span><strong>${fmt(s.weight)} kg × ${s.reps} 次</strong></button>`).join('')}${strengthEnergyDetails(r)}<p class="tip">备注：${esc(r.note||'无')}</p><div class="form-actions">${deleteBtn('strength',r.id)}<button class="btn ghost" data-act="close">关闭</button></div>`);}
  function editSet(index,recordId=null){const r=recordId?idRecord('strength',recordId):db.draft?.active;if(!r)return;const s=r.sets[index];dialog('编辑第 '+(index+1)+' 组',`<form id="record-form"><div class="form-grid">${field('weight','输入重量',s.weight,{unit:'kg',max:1000})}${field('reps','次数',s.reps,{min:1,max:1000,step:'1'})}</div><label class="check-field space-top"><input name="warmup" type="checkbox" ${s.warmup?'checked':''}>热身组</label>${formEnd('保存修改','<button type="button" class="btn danger" id="remove-set">删除本组</button>')}</form>`);const change=update=>{commit(next=>{const rr=recordId?next.strength.find(x=>x.id===recordId):next.draft.active;update(rr);rr.updatedAt=new Date().toISOString();});close();render();if(recordId)editStrength(idRecord('strength',recordId));};bindForm(fd=>change(rr=>{rr.sets[index]={...s,weight:val(fd,'weight'),reps:val(fd,'reps'),warmup:fd.get('warmup')==='on'};}));$('#remove-set').onclick=()=>{if(recordId&&r.sets.length===1){toast('这是最后一组，请在上一页删除整个动作记录');return;}confirmation('删除这一组','删除后会重新计算组数与训练容量。',()=>{change(rr=>rr.sets.splice(index,1));});};}
  function customCardio(){dialog('添加自定义有氧',`<form id="record-form">${field('name','运动名称','',{type:'text'})}<p class="tip">Demo 中自定义项目记录运动时长；已有项目会保留各自的专项字段。</p>${formEnd('添加项目')}</form>`);bindForm(fd=>{const name=String(fd.get('name')).trim();if([...F.CARDIO,...db.customCardio].includes(name))throw Error('已存在同名运动。');commit(next=>next.customCardio.push(name));close();render();toast('自定义有氧已添加');});}
  function clearDataDialog(){
    dialog('清空全部数据',`<p>将删除当前设备内本应用的身体资料、运动、饮食、睡眠、训练计划、自定义项目和进行中训练。</p><p class="tip">内置食物库与已经导出的备份文件保留。删除后无法撤销，可先导出备份。</p><button type="button" class="btn secondary space-top" data-act="export">${icon('download')}先导出备份</button><form id="record-form" class="space-top"><label class="field"><span>输入“清空”以确认</span><input name="clearConfirmation" type="text" autocomplete="off" maxlength="2" required></label><div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn ghost" data-act="close">取消</button><button type="submit" class="btn danger" id="clear-data-submit" disabled>永久清空数据</button></div></form>`);
    const input=$('[name=clearConfirmation]');input.oninput=()=>$('#clear-data-submit').disabled=input.value!=='清空';
    bindForm(fd=>{
      if(fd.get('clearConfirmation')!=='清空')throw Error('请输入“清空”后再确认。');
      const next=F.blank(),raw=JSON.stringify(next);
      if(window.AndroidStore){if(!AndroidStore.save(raw))throw Error('清空失败，原数据保持不变。请检查剩余空间后重试。');}else localStorage.setItem(KEY,raw);
      db=next;readOnly=false;storageError='';selected=F.localDate();month=selected.slice(0,7);route='calendar';timerEnd=0;restEnabled=true;trend='weight';range=30;welcomed=false;onboard=false;close();render();window.scrollTo(0,0);toast('本应用数据已清空');
    });
  }
  function exportData(raw=false){const data=raw?(window.AndroidStore?AndroidStore.load():localStorage.getItem(KEY)):JSON.stringify(db,null,2);if(!data){toast('没有可导出的数据');return;}if(window.AndroidStore){AndroidStore.exportBackup(data);return;}const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dailyfitness-${F.localDate()}${raw?'-raw':''}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已生成备份文件');}
  function importData(){if(window.AndroidStore){AndroidStore.importBackup();return;}const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>4000000){toast('文件不能超过 4 MB');return;}try{confirmImport(await file.text());}catch(e){toast('备份读取失败：'+e.message);}};input.click();}
  function confirmImport(raw){try{const incoming=F.validateBackup(raw);confirmation('恢复备份',`备份包含 ${incoming.profiles.length} 条身体测量、${incoming.cardio.length+incoming.strength.length+incoming.meals.length+incoming.sleep.length} 条日常记录。恢复会替换当前设备内的全部数据，建议先导出当前备份。`,()=>{const data=JSON.stringify(incoming);if(window.AndroidStore){if(!AndroidStore.save(data))throw Error('恢复保存失败，原数据未替换');}else localStorage.setItem(KEY,data);db=incoming;storageError='';readOnly=false;welcomed=true;onboard=true;route='calendar';toast('备份已恢复');});}catch(e){dialog('无法恢复备份',`<div class="form-error">${esc(e.message)}</div><p class="tip">原记录保持不变，请选择此 Demo 导出的有效 JSON 备份。</p><div class="form-actions"><button class="btn" data-act="close">知道了</button></div>`);}}
  window.onNativeImport=raw=>confirmImport(raw);
  window.onNativeMessage=message=>toast(message);
  window.onNativeBack=()=>{if($('#modal').open){close();return;}if(route!=='calendar'){route='calendar';render();return;}if(window.AndroidStore)AndroidStore.finishApp();};
  document.addEventListener('click',e=>{const b=e.target.closest('button,[data-muscle]');if(!b)return;try{
    if(b.dataset.nav){route=b.dataset.nav;if(route==='workout'&&!db.draft)route='train';close();render();window.scrollTo(0,0);return;}
    if(b.dataset.date){selected=b.dataset.date;month=selected.slice(0,7);render();return;}
    if(b.dataset.edit){const k=b.dataset.edit,r=idRecord(k,b.dataset.id);if(k==='cardio')openCardio(r);else if(k==='meals')openMeal(r);else if(k==='sleep')openSleep(r);else if(k==='profiles')openProfile(r);else editStrength(r);return;}
    if(b.dataset.delete){const kind=b.dataset.delete,id=b.dataset.id;if(kind==='plans'&&db.draft?.planId===id){toast('请先结束该计划的进行中训练');return;}confirmation('删除这条记录','删除后无法撤销，相关报告和曲线会同步更新。',()=>{commit(next=>next[kind]=next[kind].filter(r=>r.id!==id));toast('已删除');});return;}
    if(b.dataset.startPlan){const p=db.plans.find(p=>p.id===b.dataset.startPlan),i=Number(b.dataset.day);startSession('split',p.days[i],p.id,i);return;}
    if(b.dataset.trendGroup){trend=Object.keys(trendMetrics).find(k=>trendMetrics[k][2]===b.dataset.trendGroup);render();return;}
    if(b.hasAttribute('data-edit-set')){editSet(Number(b.dataset.editSet));return;}
    if(b.hasAttribute('data-record-set')){editSet(Number(b.dataset.recordSet),b.dataset.id);return;}
    switch(b.dataset.act){
      case'close':close();break;
      case'skip-welcome':welcomed=true;onboard=true;render();break;
      case'prev-month':case'next-month':{const date=new Date(month+'-01T12:00:00');date.setMonth(date.getMonth()+(b.dataset.act==='prev-month'?-1:1));month=F.localDate(date).slice(0,7);render();break;}
      case'today':selected=F.localDate();month=selected.slice(0,7);render();break;
      case'add-sport':dialog('添加运动',`<p class="tip">记录日期：${selected}</p><div class="stack space-top"><button class="btn secondary wide" data-act="cardio">${icon('activity')}有氧运动</button><button class="btn secondary wide" data-act="go-plans">${icon('folder')}分化计划训练</button><button class="btn secondary wide" data-act="big3">${icon('weight')}三大项</button><button class="btn ghost wide" data-act="free-strength">自由力量训练</button></div>`);break;
      case'go-plans':close();route='train';render();break;
      case'cardio':openCardio();break;
      case'meal':openMeal();break;
      case'sleep':openSleep();break;
      case'profile':openProfile();break;
      case'plan':openPlan();break;
      case'plan-edit':openPlan(db.plans.find(p=>p.id===b.dataset.id));break;
      case'free-strength':chooseMuscle();break;
      case'big3':if(db.draft){route='workout';close();render();toast('请先结束当前训练');}else startSession('big3','胸');break;
      case'exercise':openExercise();break;
      case'finish-action':if(db.draft?.active?.sets.length){commit(next=>{next.draft.active.updatedAt=new Date().toISOString();next.draft.finished.push(next.draft.active);next.draft.active=null;});timerEnd=0;render();toast('动作已完成，可以添加下一动作');}break;
      case'finish-workout':finishWorkout();break;
      case'discard-workout':confirmation('放弃本次训练','本次未结束训练中的动作和组记录将被删除，分化计划不推进。',()=>{commit(next=>next.draft=null);timerEnd=0;route='train';});break;
      case'timer-reset':timerEnd=Date.now()+90000;tick();break;
      case'timer-skip':timerEnd=0;if($('#timer-text'))$('#timer-text').textContent='已跳过';break;
      case'note':{const a=db.draft.active;dialog('动作备注',`<form id="record-form"><label class="field"><span>${esc(a.name)}的备注</span><textarea name="note" maxlength="1000">${esc(a.note)}</textarea></label>${formEnd('保存备注')}</form>`);bindForm(fd=>{commit(next=>next.draft.active.note=String(fd.get('note')));close();toast('备注已保存');});break;}
      case'history':{const a=db.draft.active,rs=db.strength.filter(r=>r.name===a.name&&r.equipment===a.equipment).sort((x,y)=>y.date.localeCompare(x.date));dialog(a.name+' · 历史',rs.length?rs.map(r=>`<div class="record-row"><span>${r.date}</span><span style="font-size:12px;text-align:right">${F.groupedSets(r).map(g=>`${fmt(g.weight)} kg × ${g.reps} 次 × ${g.count} 组`).join('<br>')}</span></div>`).join(''):'<p class="tip">还没有这个动作的历史记录。</p>');break;}
      case'custom-cardio':customCardio();break;
      case'export':exportData();break;
      case'clear-data':clearDataDialog();break;
      case'session-energy':editSessionEnergy(b.dataset.id);break;
      case'raw-export':exportData(true);break;
      case'import':importData();break;
      case'about':dialog('daily fitness · Demo 0.3',`<p>离线记录运动、饮食与睡眠。</p><p class="tip">手动营养素换算：蛋白质 4、碳水 4、脂肪 9 kcal/g；食物估算使用所选官方食物数据库的能量值。<a href="https://www.nal.usda.gov/programs/fnic" target="_blank" rel="noopener">USDA 来源</a></p><p class="tip">成人基础代谢采用 Mifflin–St Jeor 公式，上下浮动 10% 作为展示范围；不是实测区间、全天消耗或建议摄入目标。<a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">原始公式</a></p><p class="tip">哑铃按总重；杠铃输入两侧片重，再加当次杆重。容量按外部总重 × 次数相加，含已记录热身组。</p><p class="tip">Demo 使用本地 Web 界面与安卓安装壳，JSON 本地保存。食物库来自食药署中文食品与 USDA 的公开数据快照，可离线查找；原始食物名与数据版本可在饮食录入中查看。未接入云端或健康设备。</p><div class="form-actions"><button class="btn" data-act="close">知道了</button></div>`);break;
    }
  }catch(err){toast(err.message);}});
  $('#modal').addEventListener('close',()=>{$('#modal').onclick=null;});
  $('#modal').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-muscle]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  render();
})();
